import{z as o,x as A,o as e,c as p,q as r,j as l,D as E,d as s,s as i,S as n}from"./chunks/framework.C8m1ZpeB.js";const m=JSON.parse('{"title":"GRE 与隧道","description":"","frontmatter":{"title":"GRE 与隧道","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/gre-tunnels.md","filePath":"cs/gre-tunnels.md","lastUpdated":1791413859000}'),B={name:"cs/gre-tunnels.md"};function d(P,a,R,T,c,_){const t=A("Mermaid");return e(),p("div",null,[a[2]||(a[2]=r('<h1 id="gre-与隧道" tabindex="-1">GRE 与隧道 <a class="header-anchor" href="#gre-与隧道" aria-label="Permalink to &quot;GRE 与隧道&quot;">​</a></h1><div class="epigraph"><p>GRE 把任意载荷装进另一张 IP 头，中间只转发外层；简单、无状态，校验、MTU 与安全都要另配。</p><footer>—— 据 RFC 2784 GRE；RFC 2890 密钥与序号；RFC 7676 IPv6 上的 GRE 整理</footer></div><p><a href="/cs/vxlan-overlay">VXLAN</a> 与 <a href="/cs/mpls">MPLS</a> 已是隧道。<a href="/cs/evpn">上一课</a> 是控制面。缺口是<strong>最简 IP 隧道</strong>：GRE、何时用、与 IPsec/NVGRE 对照。本课不把 IGMP 写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>要把非 IP 或私网 IP 穿过只懂公网的核心：外层源/目的是隧道端点，内层原样。GRE 无内置拥塞与加密；序号可选。中间 ECMP 只看见外层五元组，熵不足则极化——VXLAN 用 UDP 源端口，GRE 常靠外层 IP 与 GRE 头。递归：隧道口的 MTU 必须小于底层，否则内层 PMTUD 黑洞（后课）。</p>',5)),(e(),l(n,null,{default:E(()=>[i(t,{id:"mermaid-13",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E5%86%85%E5%B1%82%E5%8C%85%201500%20%E5%AD%97%E8%8A%82%22%5D%20--%3E%20B%5B%22%E5%8A%A0%204%20%E5%AD%97%E8%8A%82%20GRE%20%E5%A4%B4%22%5D%0A%20%20B%20--%3E%20C%5B%22%E5%8A%A0%2020%20%E5%AD%97%E8%8A%82%E5%A4%96%E5%B1%82%20IP%20%E5%A4%B4%22%5D%0A%20%20C%20--%3E%20D%7B%22%E8%B6%85%E8%BF%87%E5%BA%95%E5%B1%82%E9%93%BE%E8%B7%AF%20MTU%201500%EF%BC%9F%22%7D%0A%20%20D%20--%20%22%E6%98%AF%22%20--%3E%20E%5B%22%E4%B8%AD%E9%97%B4%E8%B7%AF%E7%94%B1%E5%99%A8%E4%B8%A2%E5%8C%85%E4%B8%94%E4%B8%8D%E5%9B%9E%20ICMP%22%5D%0A%20%20D%20--%20%22%E5%90%A6%EF%BC%88%E9%9A%A7%E9%81%93%E5%8F%A3%20MTU%20%E5%B7%B2%E8%B0%83%E5%B0%8F%EF%BC%89%22%20--%3E%20F%5B%22%E5%86%85%E5%B1%82%E5%85%88%E5%88%86%E6%AE%B5%EF%BC%8C%E6%AD%A3%E5%B8%B8%E8%BD%AC%E5%8F%91%22%5D%0A%20%20E%20--%3E%20G%5B%22%E5%A4%A7%E5%8C%85%E5%8D%A1%E6%AD%BB%EF%BC%8C%E5%B0%8F%E5%8C%85%E9%80%9A%EF%BC%9APMTUD%20%E9%BB%91%E6%B4%9E%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r('<p>不要把 GRE 当成 VXLAN 替代租户隔离：没有 VNI 标准语义，除非你自己编 key。</p><p><span class="marginnote">RFC 2784。PPTP 等历史用法不展开。IPsec 隧道模式是安全对照，不是 GRE 的升级补丁。</span></p><p><span class="marginnote">数字实例：底层以太网 MTU 是 1500 字节，GRE 头至少 4 字节、外层 IP 头 20 字节，所以隧道口的有效 MTU 只剩 1476。若不把隧道口 MTU 调小，内层 1500 字节的包封装后变成 1524 字节，中间必丢。</span></p><p><span class="marginnote">直觉类比：ECMP 分箱就像快递分拣只扫外层条码。所有 GRE 包的外层地址都是同一对隧道端点，分拣机看到的「条码」几乎一样，容易把所有包扔进同一条传送带——这就是「熵不足则极化」，某些链路挤爆、其余闲置。</span></p><h3 id="无状态封装" tabindex="-1">无状态封装 <a class="header-anchor" href="#无状态封装" aria-label="Permalink to &quot;无状态封装&quot;">​</a></h3><p>中间只看外层 IP。无内置加密与 VNI 语义。Keepalive 是实现特性。递归 MTU 是黑洞温床。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照：GRE / VXLAN / MPLS / IP-in-IP。画：内层包 → GRE → 外层 IP → 核心 LPM。与蜂窝 GTP 同类：锚点隧道。</p>',8)),(e(),l(n,null,{default:E(()=>[i(t,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20INN%5B%22%E5%86%85%E5%B1%82%E6%8A%A5%E6%96%87%22%5D%20--%3E%20GRE%5B%22GRE%20%E5%A4%B4%22%5D%0A%20%20GRE%20--%3E%20OUT%5B%22%E5%A4%96%E5%B1%82%20IP%22%5D%0A%20%20OUT%20--%3E%20CORE%5B%22%E4%B8%AD%E9%97%B4%E5%8F%AA%E7%9C%8B%E5%A4%96%E5%B1%82%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[s(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>OSPF 可在隧道上建邻接（小心递归与 MTU）。流量工程可把 GRE 当一条逻辑边，度量人工设。RSTP 不应把隧道当二层边除非你做了桥——那会把环带进核心。卫星链路上 GRE 只加头税，不减 RTT。</p><p>Keepalive 是实现特性，标准 GRE 无强制 Hello。</p><p><span class="marginnote">常见误区：初学者以为 GRE 隧道像一条保持着的有状态连接，断了会有协议来报修。实际上 RFC 2784 的 GRE 完全无状态，两端不交换任何心跳； keepalive 是各家设备厂商自己加的实现特性，能不能用要看具体平台。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 WireGuard 的加密握手。多播 IGMP/PIM 是下一课。后课默认：GRE 是无状态封装；隔离与安全要另加。</p><p>把整个互联网当 GRE 网是 NAT 穿越的权宜，不是架构目标。</p><p>下一课<a href="/cs/multicast-igmp-pim">多播 IGMP / PIM</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>GRE：外层 IP 转运，中间无内层状态。</li><li>熵与 MTU 是隧道共同税。</li><li>不提供 VPN 密钥语义或 VNI。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：RFC 2784；RFC 2890。</li></ul>',10))])}const G=o(B,[["render",d]]);export{m as __pageData,G as default};
